use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";
const HEX: &[u8; 16] = b"0123456789ABCDEF";

/// Percent-encode every byte outside the RFC 3986 unreserved set, so that
/// adversarial feed text cannot alter the query string or the URL structure.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut kept = Vec::with_capacity(items.len());

        for item in items {
            // Enrichment is requested for every input item. Its result is
            // deliberately discarded so the node's output is unchanged.
            let url = format!("{}{}", ENRICH_BASE, percent_encode(&item.text));
            let _ = http_client::fetch(&url);

            if state_read::get(&item.id).is_none() {
                kept.push(item);
            }
        }

        kept
    }
}

export!(Node);
